export function getStudyBlocksForDay(day: number): StudyBlock[] {
  if (day === 2) {
    return day2StudyBlocks;
  }
  if (day === 3) {
    return day3StudyBlocks;
  }
  if (day === 4) {
    return day4StudyBlocks;
  }
  if (day === 5) {
    return day5StudyBlocks;
  }
  if (day === 6) {
    return day6StudyBlocks;
  }
  if (day === 7) {
    return day7StudyBlocks;
  }
  if (day === 8) {
    return day8StudyBlocks;
  }
  if (day === 9) {
    return day9StudyBlocks;
  }
  if (day === 10) {
    return day10StudyBlocks;
  }
  if (day === 11) {
    return day11StudyBlocks;
  }
  if (day === 12) {
    return day12StudyBlocks;
  }
  if (day === 13) {
    return day13StudyBlocks;
  }
  if (day === 14) {
    return day14StudyBlocks;
  }
  if (day === 15) {
    return day15StudyBlocks;
  }
  if (day === 16) {
    return day16StudyBlocks;
  }
  if (day === 17) {
    return day17StudyBlocks;
  }
  if (day === 18) {
    return day18StudyBlocks;
  }
  if (day === 19) {
    return day19StudyBlocks;
  }
  if (day === 20) {
    return day20StudyBlocks;
  }
  if (day === 21) {
    return day21StudyBlocks;
  }
  if (day === 22) {
    return day22StudyBlocks;
  }
  if (day === 23) {
    return day23StudyBlocks;
  }
  if (day === 24) {
    return day24StudyBlocks;
  }
  if (day === 25) {
    return day25StudyBlocks;
  }
  if (day === 26) {
    return day26StudyBlocks;
  }
  if (day === 27) {
    return day27StudyBlocks;
  }
  if (day === 28) {
    return day28StudyBlocks;
  }
  if (day === 29) {
    return day29StudyBlocks;
  }
  if (day === 30) {
    return day30StudyBlocks;
  }
  return initialStudyBlocks; // Day 1 default
}

